```python
def removeAlmostEqualCharacters(word: str):
    n = len(word)
    # dp[i][j] 表示前 i 個字元處理完，且第 i 個字元變為字母 j (0-25) 的最小操作數
    # 初始化為無限大
    dp = [[float('inf')] * 26 for _ in range(n)]

    # 第一個字元的初始化
    first_char_idx = ord(word[0]) - ord('a')
    for j in range(26):
        dp[0][j] = 1 if j != first_char_idx else 0

    for i in range(1, n):
        current_char_idx = ord(word[i]) - ord('a')
        for curr_j in range(26):
            # 計算當前字元變為 curr_j 時，與前一個字元 prev_j 的關係
            for prev_j in range(26):
                # 檢查是否為 "almost-equal" (相同或相鄰)
                if abs(curr_j - prev_j) > 1:
                    cost = 0 if curr_j == current_char_idx else 1
                    dp[i][curr_j] = min(dp[i][curr_j], dp[i-1][prev_j] + cost)

    return min(dp[n-1])
