from functools import lru_cache

def count(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    MOD = 10**9 + 7

    @lru_cache(None)
    def dp(s, is_less, current_sum):
        if current_sum > max_sum:
            return 0
        if not s:
            return 1 if min_sum <= current_sum <= max_sum else 0

        limit = int(s[0]) if not is_less else 9
        res = 0
        for d in range(limit + 1):
            res += dp(s[1:], is_less or (d < limit), current_sum + d)
        return res % MOD

    def solve(n: str) -> int:
        # Memoization reset for different numbers
        dp.cache_clear()
        # We use a helper to handle the digit sum constraint directly in DP state
        @lru_cache(None)
        def count_upto(idx, current_sum, is_less):
            if current_sum > max_sum: return 0
            if idx == len(n):
                return 1 if min_sum <= current_sum <= max_sum else 0

            res = 0
            upper = int(n[idx]) if not is_less else 9
            for d in range(upper + 1):
                res += count_upto(idx + 1, current_sum + d, is_less or (d < upper))
            return res % MOD

        return count_upto(0, 0, False)

    # Result = Count(num2) - Count(num1 - 1)
    ans2 = solve(num2)

    # Handle num1 - 1 for strings
    val1 = int(num1)
    if val1 == 0:
        ans1 = 0
    else:
        ans1 = solve(str(val1 - 1))

    return (ans2 - ans1 + MOD) % MOD
