```python
from typing import List

def specialPerm(nums: List[int]) -> int:
    n = len(nums)
    MOD = 10**9 + 7

    # 預先計算哪些數字之間可以相鄰（其中一個能被另一個整除）
    adj = [[False] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            if nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0:
                adj[i][j] = adj[j][i] = True

    # dp[mask][last_idx] 表示當已使用的數字為 mask，且最後一個數字是 nums[last_idx] 時的排列數
    dp = [[0] * n for _ in range(1 << n)]

    # 初始化：每個數字都可以作為起點
    for i in range(n):
        dp[1 << i][i] = 1

    # 開始 DP
    for mask in range(1, 1 << n):
        for i in range(n):
            if dp[mask][i] == 0:
                continue

            # 嘗試接下一個數字 j
            for j in range(n):
                # 如果 j 還沒被使用，且 i 和 j 符合條件
                if not (mask & (1 << j)) and adj[i][j]:
                    next_mask = mask | (1 << j)
                    dp[next_mask][j] = (dp[next_mask][j] + dp[mask][i]) % MOD

    # 結果是所有包含了所有數字（mask 為全 1）且以任何數字結尾的總和
    full_mask = (1 << n) - 1
    return sum(dp[full_mask]) % MOD
```

