def longestCommonPrefix(arr1: List[int], arr2: List[int]) -> int:
    # 使用字典建立 Trie 結構
    trie = {}

    # 將 arr1 的所有數字放入 Trie 中
    for num in arr1:
        node = trie
        s_num = str(num)
        for char in s_num:
            if char not in node:
                node[char] = {}
            node = node[char]

    max_len = 0

    # 遍歷 arr2 在 Trie 中尋找最長匹配路徑
    for num in arr2:
