def maxScore(nums: List[int], x: int) -> int:
    # dp_even: max score ending at an even number
    # dp_odd: max score ending at an odd number
    dp_even = -float('inf')
    dp_odd = -float('inf')

    # Initial state: position 0
    if nums[0] % 2 == 0:
        dp_even = nums[0]
    else:
        dp_odd = nums[0]

    for i in range(1, len(nums)):
        val = nums[i]
        if val % 2 == 0:
            # Can come from previous even (no cost) or previous odd (cost x)
            dp_even = max(dp_even + val, dp_odd + val - x, val)
        else:
            # Can come from previous odd (no cost) or previous even (cost x)
            dp_odd = max(dp_odd + val, dp_even + val - x, val)

    return max(dp_even, dp_odd)
